/* eslint-disable */
import _m0 from "protobufjs/minimal";
import { AvatarMask, avatarMaskFromJSON, avatarMaskToJSON } from "./common/avatar_mask.gen";

export const protobufPackage = "decentraland.sdk.components";

/** EmoteState describes the lifecycle state of an emote playback. */
export enum EmoteState {
  /**
   * ES_STARTED - ES_STARTED indicates the emote started playing.
   * This is the zero value and is used for backward compatibility — entries
   * written by older explorers (field absent) read as "started".
   */
  ES_STARTED = 0,
  /** ES_FINISHED - ES_FINISHED indicates a non-looping emote completed naturally. */
  ES_FINISHED = 1,
  /**
   * ES_INTERRUPTED - ES_INTERRUPTED indicates playback was cancelled (movement, teleport,
   * another emote superseding it, explicit stop, or scene change).
   */
  ES_INTERRUPTED = 2,
  UNRECOGNIZED = -1,
}

export function emoteStateFromJSON(object: any): EmoteState {
  switch (object) {
    case 0:
    case "ES_STARTED":
      return EmoteState.ES_STARTED;
    case 1:
    case "ES_FINISHED":
      return EmoteState.ES_FINISHED;
    case 2:
    case "ES_INTERRUPTED":
      return EmoteState.ES_INTERRUPTED;
    case -1:
    case "UNRECOGNIZED":
    default:
      return EmoteState.UNRECOGNIZED;
  }
}

export function emoteStateToJSON(object: EmoteState): string {
  switch (object) {
    case EmoteState.ES_STARTED:
      return "ES_STARTED";
    case EmoteState.ES_FINISHED:
      return "ES_FINISHED";
    case EmoteState.ES_INTERRUPTED:
      return "ES_INTERRUPTED";
    case EmoteState.UNRECOGNIZED:
    default:
      return "UNRECOGNIZED";
  }
}

/**
 * AvatarEmoteCommand is a grow only value set, written by the explorer to report
 * avatar emote playback to the scene. It is appended to every player entity in the
 * scene (the local player and remote avatars alike).
 */
export interface PBAvatarEmoteCommand {
  emoteUrn: string;
  loop: boolean;
  /** monotonic counter */
  timestamp: number;
  mask?:
    | AvatarMask
    | undefined;
  /**
   * state describes the lifecycle event for this emote entry.
   * When absent (older explorers), defaults to ES_STARTED.
   */
  state?: EmoteState | undefined;
}

function createBasePBAvatarEmoteCommand(): PBAvatarEmoteCommand {
  return { emoteUrn: "", loop: false, timestamp: 0, mask: undefined, state: undefined };
}

export namespace PBAvatarEmoteCommand {
  export function encode(message: PBAvatarEmoteCommand, writer: _m0.Writer = _m0.Writer.create()): _m0.Writer {
    if (message.emoteUrn !== "") {
      writer.uint32(10).string(message.emoteUrn);
    }
    if (message.loop === true) {
      writer.uint32(16).bool(message.loop);
    }
    if (message.timestamp !== 0) {
      writer.uint32(24).uint32(message.timestamp);
    }
    if (message.mask !== undefined) {
      writer.uint32(32).int32(message.mask);
    }
    if (message.state !== undefined) {
      writer.uint32(40).int32(message.state);
    }
    return writer;
  }

  export function decode(input: _m0.Reader | Uint8Array, length?: number): PBAvatarEmoteCommand {
    const reader = input instanceof _m0.Reader ? input : _m0.Reader.create(input);
    let end = length === undefined ? reader.len : reader.pos + length;
    const message = createBasePBAvatarEmoteCommand();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1:
          if (tag !== 10) {
            break;
          }

          message.emoteUrn = reader.string();
          continue;
        case 2:
          if (tag !== 16) {
            break;
          }

          message.loop = reader.bool();
          continue;
        case 3:
          if (tag !== 24) {
            break;
          }

          message.timestamp = reader.uint32();
          continue;
        case 4:
          if (tag !== 32) {
            break;
          }

          message.mask = reader.int32() as any;
          continue;
        case 5:
          if (tag !== 40) {
            break;
          }

          message.state = reader.int32() as any;
          continue;
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skipType(tag & 7);
    }
    return message;
  }

  export function fromJSON(object: any): PBAvatarEmoteCommand {
    return {
      emoteUrn: isSet(object.emoteUrn) ? String(object.emoteUrn) : "",
      loop: isSet(object.loop) ? Boolean(object.loop) : false,
      timestamp: isSet(object.timestamp) ? Number(object.timestamp) : 0,
      mask: isSet(object.mask) ? avatarMaskFromJSON(object.mask) : undefined,
      state: isSet(object.state) ? emoteStateFromJSON(object.state) : undefined,
    };
  }

  export function toJSON(message: PBAvatarEmoteCommand): unknown {
    const obj: any = {};
    message.emoteUrn !== undefined && (obj.emoteUrn = message.emoteUrn);
    message.loop !== undefined && (obj.loop = message.loop);
    message.timestamp !== undefined && (obj.timestamp = Math.round(message.timestamp));
    message.mask !== undefined && (obj.mask = message.mask !== undefined ? avatarMaskToJSON(message.mask) : undefined);
    message.state !== undefined &&
      (obj.state = message.state !== undefined ? emoteStateToJSON(message.state) : undefined);
    return obj;
  }

  export function create<I extends Exact<DeepPartial<PBAvatarEmoteCommand>, I>>(base?: I): PBAvatarEmoteCommand {
    return PBAvatarEmoteCommand.fromPartial(base ?? {});
  }

  export function fromPartial<I extends Exact<DeepPartial<PBAvatarEmoteCommand>, I>>(object: I): PBAvatarEmoteCommand {
    const message = createBasePBAvatarEmoteCommand();
    message.emoteUrn = object.emoteUrn ?? "";
    message.loop = object.loop ?? false;
    message.timestamp = object.timestamp ?? 0;
    message.mask = object.mask ?? undefined;
    message.state = object.state ?? undefined;
    return message;
  }
}

type Builtin = Date | Function | Uint8Array | string | number | boolean | undefined;

export type DeepPartial<T> = T extends Builtin ? T
  : T extends Array<infer U> ? Array<DeepPartial<U>> : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends { $case: string } ? { [K in keyof Omit<T, "$case">]?: DeepPartial<T[K]> } & { $case: T["$case"] }
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

type KeysOfUnion<T> = T extends T ? keyof T : never;
export type Exact<P, I extends P> = P extends Builtin ? P
  : P & { [K in keyof P]: Exact<P[K], I[K]> } & { [K in Exclude<keyof I, KeysOfUnion<P>>]: never };

function isSet(value: any): boolean {
  return value !== null && value !== undefined;
}
